        private async void Add_New_User_Btn_Click(object sender, EventArgs e)
        {
            User user = new User();
            if (!ValidateString(Add_Username_TextBox, "يرجى إدخال اسم المستخدم الخاص بتسجيل الدخول")) return;
            if (!ValidateString(Username_Add_TextBox, "يرجى إدخال اسم المستخدم")) return;
            if (!ValidateString(Add_User_Recovery_TextBox, "يرجى إدخال كلمه الاسترجاع")) return;
            if (!ValidateString(Add_User_Password_TextBox, "يرجى إدخال كلمه المرور")) return;
            if (Add_Username_TextBox.TextLength< 3)
            {
                MyHelper.SnackbarShow(this, this.Snackbar, "يجب ان يكون اسم المستخدم مميز و اكبر من 3 حروف واقل من 20", Bunifu.UI.WinForms.BunifuSnackbar.MessageTypes.Error);
                Add_Username_TextBox.Focus();
                Add_Username_TextBox.Select();
                return;
            }
            if (Username_Add_TextBox.TextLength < 7|| Username_Add_TextBox.TextLength > 30)
            {
                MyHelper.SnackbarShow(this, this.Snackbar, "يجب ان يكون اسم المستخدم اكبر من 7 حروف واقل من 30", Bunifu.UI.WinForms.BunifuSnackbar.MessageTypes.Error);
                Username_Add_TextBox.Focus();
                Username_Add_TextBox.Select();
                return;
            }
            if (Add_User_Recovery_TextBox.TextLength < 3)
            {
                MyHelper.SnackbarShow(this, this.Snackbar, "يجب ان يكون كلمه الاسترجاع مميزه و اكبر من 3 حروف", Bunifu.UI.WinForms.BunifuSnackbar.MessageTypes.Error);
                Add_User_Recovery_TextBox.Focus();
                Add_User_Recovery_TextBox.Select();
                return;
            }
            PermissionRepo permissionRepo = new PermissionRepo();
            bool isEmpty = await permissionRepo.IsEmpty();
            int userpermissionid =0;
            if (isEmpty)
            {
                UserPermissions userPermissions = new UserPermissions("المدير");
                bool isSuccess = await permissionRepo.Add(userPermissions);
                if (!isSuccess) return;
                userpermissionid = userPermissions.Id;
            }
            else 
            {
                userpermissionid = permissionRepo.GetFirstAdmin();
            }
            if (userpermissionid == 0) return;
            user.Name = Username_Add_TextBox.Text;
            user.NameEn = Username_Add_TextBox.Text;
            user.UserName = Add_Username_TextBox.Text;
            user.RecoverWord = Hasher.Hash(Add_User_Recovery_TextBox.Text);
            user.Password = Hasher.Hash(Add_User_Password_TextBox.Text);
            user.Phone = "00000000000";
            user.Photo =ImageToByteArray( CodeToImage(""),System.Drawing.Imaging.ImageFormat.Png);
            user.UserPermissionId = userpermissionid;
            user.IsActive=true;
            user.IsDeleted = false;
            bool IsSuccess= await this.user.Add(user);
            if (IsSuccess)
            {
                User TrueUser = await this.user.ValidateUser(user.UserName, user.Password);

                MyHelper.OpenForm<MainMenuForm>(TrueUser);
                Hide();
            }
        }
        public bool ValidateString(Guna.UI2.WinForms.Guna2TextBox textBox, string ErrorCaption)
        {
            if (string.IsNullOrEmpty(textBox.Text) || string.IsNullOrWhiteSpace(textBox.Text))
            {
                MyHelper.SnackbarShow(this, this.Snackbar, ErrorCaption,Bunifu.UI.WinForms.BunifuSnackbar.MessageTypes.Error);
                textBox.Focus();
                textBox.Select();
                return false;
            }
            return true;
        }
        private Image CodeToImage(string Code)
        {
            return Image.FromStream(new MemoryStream(Convert.FromBase64String(Code)));
        }
        public static byte[] ImageToByteArray(Image image, ImageFormat format)
        {
            if (image == null)
                throw new ArgumentNullException(nameof(image));
            if (format == null)
                throw new ArgumentNullException(nameof(format));

            using (var ms = new MemoryStream())
            {
                image.Save(ms, format);
                return ms.ToArray();
            }
        }
